// Create the exact same processing as the shell command:
// grep DATABASE_URL .env.test | base32 | tr -d = | tr A-Z a-z | head -c 60

// We need to simulate base32 encoding since Node doesn't have built-in base32
// Let me write a base32 encoder
function base32Encode(str) {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  const bytes = Buffer.from(str);
  let result = '';

  for (let i = 0; i < bytes.length; i += 5) {
    // Get 5 bytes (40 bits)
    const chunk = bytes.slice(i, i + 5);
    const bits = chunk.reduce((acc, byte, idx) => acc + (byte << (8 * (4 - idx))), 0);

    // Convert to 8 base32 characters
    for (let j = 0; j < 8; j++) {
      if (i * 8 + j * 5 < bytes.length * 8) {
        const index = (bits >> (35 - j * 5)) & 0x1F;
        result += alphabet[index];
      } else {
        result += '=';
      }
    }
  }

  return result;
}

// Encode to base32
